<?php
require_once __DIR__.'/legacy_operational_corrections.php';
function lop_tariff_preview(mysqli $db,int $actor,int $unit,int $student,int $version,array $input): array {
    lop_actor($db,$actor,$unit);$row=lf_one($db,"SELECT t.*,s.NO_INDUK,s.NAMA,s.KELAS,s.potongan_spp_nominal,o.batch_id,b.cutoff FROM legacy_op_tariffs t JOIN siswa s ON s.id=t.student_id AND s.unit_id=t.unit_id JOIN legacy_op_owners o ON o.id=t.owner_id AND o.unit_id=t.unit_id JOIN legacy_full_batches b ON b.id=o.batch_id AND b.unit_id=o.unit_id WHERE t.student_id=? AND b.state='completed'",[$student]);if(!$row||(int)$row['version']!==$version)throw new DomainException('Tarif berubah atau siswa tidak ditemukan.');
    $period=(string)($input['period']??'');$reason=trim((string)($input['reason']??''));$basis=$input['basis']??'';$expires=(int)($input['expires']??0);if(!lop_month($period)||$period<date('Y-m')||$period!==max(date('Y-m'),lful_next_period($row['cutoff']))||mb_strlen($reason)<10||mb_strlen($reason)>1000||!in_array($basis,['legacy','master'],true)||$expires<time()||$expires>time()+300)throw new DomainException('Periksa awal berlaku, dasar tarif, alasan dan masa konfirmasi.');
    if($basis==='legacy')$amount=lf_money(lf_cents($input['amount']??null));else{$rate=spp_current_effective_rate($db,$row['KELAS'],0,spp_student_effective_year($db,$row['NO_INDUK']));if($rate['year']==='Belum disiapkan'||$rate['base']<=0)throw new DomainException('Tarif master kelas belum siap.');$amount=lf_money((int)round($rate['base']*100));}
    $bills=lf_rows($db,"SELECT ts.*,EXISTS(SELECT 1 FROM spp_alokasi a JOIN spp_alokasi_batch ab ON ab.id=a.batch_id AND ab.status='active' WHERE a.tagihan_spp_id=ts.id) allocated FROM tagihan_spp ts JOIN master_spp_tahun mst ON mst.id=ts.master_spp_tahun_id WHERE ts.no_induk=? AND CONCAT(ts.tahun,'-',LPAD(ts.bulan,2,'0'))>=? AND mst.status<>'closed' ORDER BY ts.id",[$row['NO_INDUK'],$period]);$updated=0;$kept=0;foreach($bills as $bill)if(in_array($bill['status'],['open','waived'],true)&&!$bill['allocated'])$updated++;else$kept++;
    $digest=hash('sha256',lf_json([$actor,$unit,$row,$bills,$amount,$basis,$period,$reason,$expires]));return compact('row','amount','basis','period','reason','expires','updated','kept','digest');
}
function lop_tariff_apply(mysqli $db,int $actor,int $unit,int $student,int $version,array $input,string $digest,string $key): void {
    if(($input['confirmation']??'')!=='UBAH DASAR TARIF'||!preg_match('/^[a-f0-9]{64}$/D',$key))throw new DomainException('Konfirmasi perubahan tarif diperlukan.');$db->query('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$db->begin_transaction();try{lop_actor($db,$actor,$unit,true);$prior=lf_one($db,'SELECT * FROM legacy_op_audit WHERE request_key=? FOR UPDATE',[$key]);if($prior){if((int)$prior['actor_id']!==$actor||$prior['entity_type']!=='tariff'||(int)$prior['entity_id']!==$student||(json_decode($prior['after_data'],true)['digest']??'')!==$digest)throw new DomainException('Kunci sudah digunakan.');$db->commit();return;}lf_one($db,'SELECT id FROM siswa WHERE id=? FOR UPDATE',[$student]);$t=lf_one($db,'SELECT * FROM legacy_op_tariffs WHERE student_id=? FOR UPDATE',[$student]);if(!$t)throw new DomainException('Dasar tarif tidak ditemukan.');$s=lf_one($db,'SELECT NO_INDUK,potongan_spp_nominal FROM siswa WHERE id=?',[$student]);lf_rows($db,'SELECT id FROM tagihan_spp WHERE no_induk=? ORDER BY id FOR UPDATE',[$s['NO_INDUK']]);$preview=lop_tariff_preview($db,$actor,$unit,$student,$version,$input);if(!hash_equals($digest,$preview['digest']))throw new DomainException('Dampak perubahan tarif berubah. Periksa ulang.');
        lf_query($db,'UPDATE legacy_op_tariffs SET basis=?,amount=?,version=version+1 WHERE id=?',[$preview['basis'],$preview['amount'],$t['id']]);$net=spp_net_tariff((float)$preview['amount'],(float)$s['potongan_spp_nominal']);
        foreach(lf_rows($db,"SELECT ts.* FROM tagihan_spp ts JOIN master_spp_tahun mst ON mst.id=ts.master_spp_tahun_id WHERE ts.no_induk=? AND CONCAT(ts.tahun,'-',LPAD(ts.bulan,2,'0'))>=? AND mst.status<>'closed' AND ts.status IN ('open','waived') AND NOT EXISTS(SELECT 1 FROM spp_alokasi a JOIN spp_alokasi_batch ab ON ab.id=a.batch_id AND ab.status='active' WHERE a.tagihan_spp_id=ts.id)",[$s['NO_INDUK'],$preview['period']]) as $bill)lf_query($db,'UPDATE tagihan_spp SET tarif_dasar_snapshot=?,potongan_nominal_ditetapkan_snapshot=?,potongan_nominal_snapshot=?,nominal_tagihan=?,status=? WHERE id=?',[$preview['amount'],$net['discount_amount'],$net['discount'],$net['net'],$net['net']>0?'open':'waived',$bill['id']]);
        lf_query($db,'UPDATE siswa SET SPP_PERBULAN=? WHERE id=?',[$net['net'],$student]);lf_query($db,'INSERT INTO legacy_op_audit(unit_id,actor_id,entity_type,entity_id,request_key,reason,before_data,after_data) VALUES(?,?,?,?,?,?,?,?)',[$unit,$actor,'tariff',$student,$key,$preview['reason'],lf_json($t),lf_json($preview)]);$batch=$preview['row']['batch_id'];$b=lf_one($db,'SELECT manifest FROM legacy_full_batches WHERE id=? FOR UPDATE',[$batch]);$m=json_decode($b['manifest'],true);$m['working_digest']=lop_working_digest($db,$batch);lf_query($db,'UPDATE legacy_full_batches SET manifest=? WHERE id=?',[lf_json($m),$batch]);$db->commit();
    }catch(Throwable $e){$db->rollback();throw $e;}
}
